WITH counts AS (
  SELECT c.category_id, c.name, COUNT(fc.film_id) AS film_count
  FROM category c
  LEFT JOIN film_category fc ON c.category_id = fc.category_id
  GROUP BY c.category_id, c.name
), min_ct AS (
  SELECT MIN(film_count) AS min_count FROM counts
)
SELECT name, film_count FROM counts WHERE film_count = (SELECT min_count FROM min_ct) ORDER BY name;

